window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f13b980e1b401bb0"]={"versions": [{"id": "FIG-f13b980e1b401bb0", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Architektur-/Blockdiagramm eines Testsystems nach dem standardisierten TTCN-3-Referenzmodell (gemäß ETSI ES 201 873-5 [TRI] und ETSI ES 201 873-6 [TCI]).</li>\n<li><strong>Architektur-Kontext:</strong> <code>AUTOSAR_CTSpec_Background</code> (Release R3.0.7) zur formalen Konformitätsprüfung (Conformance Testing) von Basic Software (BSW)-Modulen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der abstrakten, plattformunabhängigen Testfall-Logik (TTCN-3 Executable) von den konkreten, hardware-, bus- und werkzeugspezifischen Adaptern sowie den Steuerungs- und Logging-Schnittstellen. Ziel ist eine hersteller- und plattformunabhängige Testautomatisierung für AUTOSAR-Stacks.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zentrale Ausführungseinheit:</strong></li>\n<li><code>TTCN-3 Executable (TE)</code> (zentraler oranger Block): Kern-Engine zur Ausführung kompilierter oder interpretierter TTCN-3-Testfälle; verwaltet Testkomponenten (MTC, PTCs), Kontrollfluss und Verdicts (<code>none</code>, <code>pass</code>, <code>inconclusive</code>, <code>fail</code>, <code>error</code>).</li>\n<li><strong>TTCN-3 Control Interfaces (TCI, ETSI ES 201 873-6):</strong></li>\n<li><code>Test Management (TM)</code> (oberer linker Block): Steuerung von Testkampagnen, Testsuite-Selektion, Parametrierung und Bereitstellung von Konfigurationsdaten.</li>\n<li><code>Test Logging (TL)</code> (oberer rechter Block): Ereignisprotokollierung, Trace-Erfassung und Verdict-Aufzeichnung.</li>\n<li><code>Component Handling (CH)</code> (linker Block): Orchestrierung verteilter Testkomponenten (Erzeugung, Ausführung, Terminierung und Inter-Komponenten-Kommunikation von MTC/PTCs).</li>\n<li><code>Data Converting (CoDec)</code> (rechter Block): Bidirektionale Konvertierung/Serialisierung zwischen abstrakten TTCN-3-Datentypen (Templates/Records) und bit-/bytegenauen Repräsentationen (PDUs, Frames, Byte-Arrays).</li>\n<li><strong>TTCN-3 Runtime Interfaces (TRI, ETSI ES 201 873-5):</strong></li>\n<li><code>System Adapter (SA)</code> (unterer linker Block mit Verbindung zum Prüfling): Realisiert die physikalische und protokollarische Kommunikation mit dem SUT via Bus-Transceiver, Debugger-Interfaces oder API-Wrapper.</li>\n<li><code>Platform Adapter (PA)</code> (unterer rechter Block): Stellt Zielsystemdienste bereit (Hardware-/Software-Timer, hochpräzise Zeitbasis, externe Hilfsfunktionen).</li>\n<li><strong>Prüfling (SUT):</strong></li>\n<li><code>System Under Test (SUT)</code> (unterer schwarzer Block): Das zu testende AUTOSAR-System (BSW-Modul, BSW-Stack, RTE oder komplette ECU).</li>\n<li><strong>Beziehungen & Schnittstellen:</strong></li>\n<li>Bidirektionale Interaktionspfeile verbinden die <code>TE</code> mit allen sechs TCI/TRI-Subsystemen via standardisierter C-/Java-Schnittstellenaufrufe.</li>\n<li>Einziger Pfad zur Zielhardware/zum Prüfling verläuft exklusiv bidirektional zwischen <code>System Adapter (SA)</code> und <code>SUT</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Test-Initialisierung:</strong> <code>TM</code> stößt die Testsuite in der <code>TE</code> an; die <code>TE</code> initialisiert via TCI/TRI die Adapter (<code>tciInit</code>, <code>triInit</code>).</li>\n<li><strong>Stimulus-Pfad (Senden, synchron $\\rightarrow$ asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>TE</code> evaluiert ein abstraktes Sende-Template.</li>\n<li><code>TE</code> übergibt die Daten an <code>Data converting (CoDec)</code> (<code>tciEncode</code>), welcher die I-PDU/den Frame bitgenau serialisiert.</li>\n<li><code>TE</code> reicht den Rohdatenstrom an den <code>System Adapter</code> weiter (<code>triSend</code>).</li>\n<li><code>SA</code> treibt das Signal/den Frame physikalisch auf den Bus (z. B. CAN, FlexRay, LIN) oder ruft die BSW-Treiber-API des <code>SUT</code> auf.</li>\n<li>Parallel wird im <code>Platform Adapter</code> ein Watchdog/Timer scharfgeschaltet (<code>triStartTimer</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response- & Evaluierungspfad (Empfangen, asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SUT</code> antwortet mit Busbotschaften oder Rückgabewerten.</li>\n<li><code>SA</code> nimmt das Signal ab und reicht es asynchron in die Queue der <code>TE</code> ein (<code>triEnqueueMsg</code>).</li>\n<li><code>TE</code> ruft <code>CoDec</code> zur Deserialisierung auf (<code>tciDecode</code>), um den Bitstrom in abstrakte Werte zurückzuwandeln.</li>\n<li><code>TE</code> matcht die empfangenen Werte gegen das Soll-Template, stoppt den Timer im <code>PA</code> (<code>triStopTimer</code>) und setzt das lokale Verdict (<code>pass</code>/<code>fail</code>).</li>\n<li>Testergebnis und Ereignisse werden über <code>TL</code> (<code>tciLog</code>) persistiert und an <code>TM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ablauf des Timers im <code>PA</code> löst ein Timeout-Event (<code>triTimeout</code>) in der <code>TE</code> aus $\\rightarrow$ Abbruch des Testfalls mit Verdict <code>fail</code> oder <code>inconclusive</code>.</li>\n<li>Fehlgeschlagene Enkodierung/Dekodierung im <code>CoDec</code> erzeugt eine Laufzeit-Exception.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konformitätszertifizierung (Conformance Testing):</strong></li>\n<li>Dieses Schema bildet das normative Fundament der AUTOSAR-Konformitätstests (CTSpec) für BSW-Stacks. Zulassungen von Stacks (z. B. Can, CanIf, Com, PduR) basieren auf Testsuiten, die exakt diese TTCN-3-Schnittstellenteilung voraussetzen.</li>\n<li><strong>Einfluss auf Stack- & Treiber-Entwickler:</strong></li>\n<li><em>Blackbox-Verhalten:</em> Das SUT darf keine proprietären Test-Hooks innerhalb der Produktions-Codebasis erfordern; das Testsystem interagiert primär über standardisierte Service-Schnittstellen (SWS-APIs) oder Bus-Botschaften via <code>System Adapter</code>.</li>\n<li><em>Bit-Exactness & Padding:</em> Da der <code>CoDec</code> strikt nach AUTOSAR-SWS encodiert/decodiert, führen Compiler-Paddings, Endianness-Inkonsistenzen oder abweichende Bit-Orderings in Treiber-PDUs unmittelbar zu Testfehlschlägen im CoDec.</li>\n<li><em>Timing & Jitter-Toleranz:</em> Die Zwischenschaltung von <code>SA</code> und <code>PA</code> (z. B. über IPC, USB-zu-CAN-Transceiver) führt zu deterministischen Latenzen. BSW-Module müssen synchronisationsfähig sein (z. B. deterministische Abarbeitung über zyklische <code>*_MainFunction</code>-Aufrufe), um Falsch-Negativ-Timeouts im Testsystem zu vermeiden.</li>\n</ul>"}, {"id": "FIG-72838dc0a1cb8756", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Architektur-/Blockdiagramm eines Testsystems nach dem standardisierten TTCN-3-Referenzmodell (gemäß ETSI ES 201 873-5 [TRI] und ETSI ES 201 873-6 [TCI]).</li>\n<li><strong>Architektur-Kontext:</strong> <code>AUTOSAR_CTSpec_Background</code> (Release R3.0.7) zur formalen Konformitätsprüfung (Conformance Testing) von Basic Software (BSW)-Modulen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der abstrakten, plattformunabhängigen Testfall-Logik (TTCN-3 Executable) von den konkreten, hardware-, bus- und werkzeugspezifischen Adaptern sowie den Steuerungs- und Logging-Schnittstellen. Ziel ist eine hersteller- und plattformunabhängige Testautomatisierung für AUTOSAR-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zentrale Ausführungseinheit:</strong></li>\n<li><code>Test executable (formally described test specifications)</code> (zentraler oranger Block): Kern-Engine zur Ausführung formal beschriebener TTCN-3-Testspezifikationen; verwaltet Testkomponenten, Kontrollfluss und Verdicts.</li>\n<li><strong>TTCN-3 Control Interfaces (<code>Control Interface (TCI)</code>):</strong></li>\n<li>Durch eine Rahmenlinie links als <code>Control Interface (TCI)</code> gekennzeichnet.</li>\n<li><code>Test management (TM)</code> (oberer linker grauer Block): Steuerung von Testkampagnen, Testsuite-Selektion und Bereitstellung von Konfigurationsdaten.</li>\n<li><code>Test logging (TL)</code> (oberer rechter grauer Block): Protokollierung, Trace-Erfassung und Verdict-Aufzeichnung.</li>\n<li><code>Component handling (CH)</code> (linker grauer Block): Management und Koordination verteilter Testkomponenten.</li>\n<li><code>Data converting (CoDec)</code> (rechter grauer Block): Konvertierung und Serialisierung zwischen abstrakten Testdatenstrukturen und konkreten Bit-/Byteströmen.</li>\n<li><strong>TTCN-3 Runtime Interfaces (<code>Runtime Interface (TRI)</code>):</strong></li>\n<li>Durch eine Rahmenlinie links als <code>Runtime Interface (TRI)</code> gekennzeichnet.</li>\n<li><code>System adapter (SA)</code> (unterer linker grauer Block): Adapter zur physikalischen und protokollarischen Anbindung des Testobjekts.</li>\n<li><code>Platform adapter (PA)</code> (unterer rechter grauer Block): Bereitstellung von Zielsystemdiensten wie Timerverwaltung und Betriebssysteminteraktion.</li>\n<li><strong>Prüfling:</strong></li>\n<li><code>Test object (real or prototypical, on development machine or on ECU)</code> (unterer schwarzer Block): Das zu prüfende System/Modul, entweder als reale oder prototypische Implementierung, ausgeführt auf einer Entwicklungsmaschine oder direkt auf dem Steuergerät (ECU).</li>\n<li><strong>Beziehungen & Schnittstellen:</strong></li>\n<li>Standardisierte bidirektionale Pfeile verbinden die zentrale <code>Test executable</code> mit <code>TM</code>, <code>TL</code>, <code>CH</code>, <code>CoDec</code>, <code>SA</code> und <code>PA</code> (wobei der Pfeil zu <code>TL</code> unidirektional von der Executable zum Logger weist).</li>\n<li>Ein bidirektionaler Pfeil verbindet den <code>System adapter (SA)</code> exklusiv mit dem <code>Test object</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Test-Initialisierung:</strong> <code>TM</code> stößt die Testsuite in der <code>TE</code> an; die <code>TE</code> initialisiert via TCI/TRI die Adapter (<code>tciInit</code>, <code>triInit</code>).</li>\n<li><strong>Stimulus-Pfad (Senden, synchron $\\rightarrow$ asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>TE</code> evaluiert ein abstraktes Sende-Template.</li>\n<li><code>TE</code> übergibt die Daten an <code>Data converting (CoDec)</code> (<code>tciEncode</code>), welcher die I-PDU/den Frame bitgenau serialisiert.</li>\n<li><code>TE</code> reicht den Rohdatenstrom an den <code>System Adapter</code> weiter (<code>triSend</code>).</li>\n<li><code>SA</code> treibt das Signal/den Frame physikalisch auf den Bus (z. B. CAN, FlexRay, LIN) oder ruft die BSW-Treiber-API des <code>SUT</code> auf.</li>\n<li>Parallel wird im <code>Platform Adapter</code> ein Watchdog/Timer scharfgeschaltet (<code>triStartTimer</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response- & Evaluierungspfad (Empfangen, asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SUT</code> antwortet mit Busbotschaften oder Rückgabewerten.</li>\n<li><code>SA</code> nimmt das Signal ab und reicht es asynchron in die Queue der <code>TE</code> ein (<code>triEnqueueMsg</code>).</li>\n<li><code>TE</code> ruft <code>CoDec</code> zur Deserialisierung auf (<code>tciDecode</code>), um den Bitstrom in abstrakte Werte zurückzuwandeln.</li>\n<li><code>TE</code> matcht die empfangenen Werte gegen das Soll-Template, stoppt den Timer im <code>PA</code> (<code>triStopTimer</code>) und setzt das lokale Verdict (<code>pass</code>/<code>fail</code>).</li>\n<li>Testergebnis und Ereignisse werden über <code>TL</code> (<code>tciLog</code>) persistiert und an <code>TM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ablauf des Timers im <code>PA</code> löst ein Timeout-Event (<code>triTimeout</code>) in der <code>TE</code> aus $\\rightarrow$ Abbruch des Testfalls mit Verdict <code>fail</code> oder <code>inconclusive</code>.</li>\n<li>Fehlgeschlagene Enkodierung/Dekodierung im <code>CoDec</code> erzeugt eine Laufzeit-Exception.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Testkonformität:</strong> Das Diagramm konkretisiert die standardisierte ETSI-TTCN-3-Testsystemarchitektur (ES 201 873-5 / ES 201 873-6) für AUTOSAR-Konformitätstests.</li>\n<li><strong>Einsatzbereich des Testobjekts:</strong> Die explizite Auszeichnung des Testobjekts als „real or prototypical, on development machine or on ECU“ verdeutlicht, dass die Testspezifikationen sowohl für virtuelle Tests (vECU / Host-Umgebung) als auch für Hardware-in-the-Loop- bzw. Target-ECU-Tests wiederverwendbar ausgelegt sind.</li>\n<li><strong>Trennungsprinzip:</strong> Strikte Entkopplung der abstrakten Testfall-Definition (<code>Test executable</code>) von werkzeugspezifischem Kampagnen- und Komponenten-Management (<code>TCI</code>) sowie plattform- und bustypabhängiger Hardware-/Treiber-Adaption (<code>TRI</code>).</li>\n</ul>"}, {"id": "FIG-237692b7194582fd", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Konzeptionelles Architektur-/Blockdiagramm eines Testsystems nach dem standardisierten TTCN-3-Referenzmodell (gemäß ETSI ES 201 873-5 [TRI] und ETSI ES 201 873-6 [TCI]).</li>\n<li><strong>Architektur-Kontext:</strong> <code>AUTOSAR_CTSpec_Background</code> (Release R3.0.7) zur formalen Konformitätsprüfung (Conformance Testing) von Basic Software (BSW)-Modulen.</li>\n<li><strong>Technischer Zweck:</strong> Trennung der abstrakten, plattformunabhängigen Testfall-Logik (TTCN-3 Executable) von den konkreten, hardware-, bus- und werkzeugspezifischen Adaptern sowie den Steuerungs- und Logging-Schnittstellen. Ziel ist eine hersteller- und plattformunabhängige Testautomatisierung für AUTOSAR-Stacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zentrale Ausführungseinheit:</strong></li>\n<li><code>Test executable (formally described test specifications)</code> (zentraler oranger Block): Kern-Engine zur Ausführung formal beschriebener TTCN-3-Testspezifikationen; verwaltet Testkomponenten, Kontrollfluss und Verdicts.</li>\n<li><strong>TTCN-3 Control Interfaces (<code>Control Interface (TCI)</code>):</strong></li>\n<li>Durch eine Rahmenlinie links als <code>Control Interface (TCI)</code> gekennzeichnet.</li>\n<li><code>Test management (TM)</code> (oberer linker grauer Block): Steuerung von Testkampagnen, Testsuite-Selektion und Bereitstellung von Konfigurationsdaten.</li>\n<li><code>Test logging (TL)</code> (oberer rechter grauer Block): Protokollierung, Trace-Erfassung und Verdict-Aufzeichnung.</li>\n<li><code>Component handling (CH)</code> (linker grauer Block): Management und Koordination verteilter Testkomponenten.</li>\n<li><code>Data converting (CoDec)</code> (rechter grauer Block): Konvertierung und Serialisierung zwischen abstrakten Testdatenstrukturen und konkreten Bit-/Byteströmen.</li>\n<li><strong>TTCN-3 Runtime Interfaces (<code>Runtime Interface (TRI)</code>):</strong></li>\n<li>Durch eine Rahmenlinie links als <code>Runtime Interface (TRI)</code> gekennzeichnet.</li>\n<li><code>System adapter (SA)</code> (unterer linker grauer Block): Adapter zur physikalischen und protokollarischen Anbindung des Testobjekts.</li>\n<li><code>Platform adapter (PA)</code> (unterer rechter grauer Block): Bereitstellung von Zielsystemdiensten wie Timerverwaltung und Betriebssysteminteraktion.</li>\n<li><strong>Prüfling:</strong></li>\n<li><code>Test object (real or prototypical, on development machine or on ECU)</code> (unterer schwarzer Block): Das zu prüfende System/Modul, entweder als reale oder prototypische Implementierung, ausgeführt auf einer Entwicklungsmaschine oder direkt auf dem Steuergerät (ECU).</li>\n<li><strong>Beziehungen & Schnittstellen:</strong></li>\n<li>Standardisierte bidirektionale Pfeile verbinden die zentrale <code>Test executable</code> mit <code>TM</code>, <code>TL</code>, <code>CH</code>, <code>CoDec</code>, <code>SA</code> und <code>PA</code> (wobei der Pfeil zu <code>TL</code> unidirektional von der Executable zum Logger weist).</li>\n<li>Ein bidirektionaler Pfeil verbindet den <code>System adapter (SA)</code> exklusiv mit dem <code>Test object</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Test-Initialisierung:</strong> <code>TM</code> stößt die Testsuite in der <code>TE</code> an; die <code>TE</code> initialisiert via TCI/TRI die Adapter (<code>tciInit</code>, <code>triInit</code>).</li>\n<li><strong>Stimulus-Pfad (Senden, synchron $\\rightarrow$ asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>TE</code> evaluiert ein abstraktes Sende-Template.</li>\n<li><code>TE</code> übergibt die Daten an <code>Data converting (CoDec)</code> (<code>tciEncode</code>), welcher die I-PDU/den Frame bitgenau serialisiert.</li>\n<li><code>TE</code> reicht den Rohdatenstrom an den <code>System Adapter</code> weiter (<code>triSend</code>).</li>\n<li><code>SA</code> treibt das Signal/den Frame physikalisch auf den Bus (z. B. CAN, FlexRay, LIN) oder ruft die BSW-Treiber-API des <code>SUT</code> auf.</li>\n<li>Parallel wird im <code>Platform Adapter</code> ein Watchdog/Timer scharfgeschaltet (<code>triStartTimer</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Response- & Evaluierungspfad (Empfangen, asynchron):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SUT</code> antwortet mit Busbotschaften oder Rückgabewerten.</li>\n<li><code>SA</code> nimmt das Signal ab und reicht es asynchron in die Queue der <code>TE</code> ein (<code>triEnqueueMsg</code>).</li>\n<li><code>TE</code> ruft <code>CoDec</code> zur Deserialisierung auf (<code>tciDecode</code>), um den Bitstrom in abstrakte Werte zurückzuwandeln.</li>\n<li><code>TE</code> matcht die empfangenen Werte gegen das Soll-Template, stoppt den Timer im <code>PA</code> (<code>triStopTimer</code>) und setzt das lokale Verdict (<code>pass</code>/<code>fail</code>).</li>\n<li>Testergebnis und Ereignisse werden über <code>TL</code> (<code>tciLog</code>) persistiert und an <code>TM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ablauf des Timers im <code>PA</code> löst ein Timeout-Event (<code>triTimeout</code>) in der <code>TE</code> aus $\\rightarrow$ Abbruch des Testfalls mit Verdict <code>fail</code> oder <code>inconclusive</code>.</li>\n<li>Fehlgeschlagene Enkodierung/Dekodierung im <code>CoDec</code> erzeugt eine Laufzeit-Exception.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Architektur- und Testkonformität:</strong> Das Diagramm konkretisiert die standardisierte ETSI-TTCN-3-Testsystemarchitektur (ES 201 873-5 / ES 201 873-6) für AUTOSAR-Konformitätstests.</li>\n<li><strong>Einsatzbereich des Testobjekts:</strong> Die explizite Auszeichnung des Testobjekts als „real or prototypical, on development machine or on ECU“ verdeutlicht, dass die Testspezifikationen sowohl für virtuelle Tests (vECU / Host-Umgebung) als auch für Hardware-in-the-Loop- bzw. Target-ECU-Tests wiederverwendbar ausgelegt sind.</li>\n<li><strong>Trennungsprinzip:</strong> Strikte Entkopplung der abstrakten Testfall-Definition (<code>Test executable</code>) von werkzeugspezifischem Kampagnen- und Komponenten-Management (<code>TCI</code>) sowie plattform- und bustypabhängiger Hardware-/Treiber-Adaption (<code>TRI</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-f13b980e1b401bb0", "to": "FIG-72838dc0a1cb8756", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Textbeschriftungen ergänzt: Alle zuvor unbeschrifteten Blöcke und Schnittstellengrenzen sind nun explizit typografisch ausgewiesen:</li>\n<li>Zentraler oranger Block: Beschriftet mit „Test executable (formally described test specifications)“.</li>\n<li>Oberer linker Block: Beschriftet mit „Test management (TM)“.</li>\n<li>Oberer rechter Block: Beschriftet mit „Test logging (TL)“.</li>\n<li>Unterer linker Block: Beschriftet mit „System adapter (SA)“.</li>\n<li>Unterer rechter Block: Beschriftet mit „Platform adapter (PA)“.</li>\n<li>Unterer schwarzer Block: Beschriftet mit „Test object (real or prototypical, on development machine or on ECU)“.</li>\n<li>Obere/mittlere Trennlinie links: Beschriftet mit „Control Interface (TCI)“.</li>\n<li>Untere Trennlinie links: Beschriftet mit „Runtime Interface (TRI)“.</li>\n<li>Grafische Struktur, Blockanordnung und Pfeilverbindungen sind unverändert.</li>\n</ul>"}, {"from": "FIG-72838dc0a1cb8756", "to": "FIG-237692b7194582fd", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
